<template><el-dialog :title="titles[action] || '处理待办'" :visible.sync="innerVisible" width="520px" append-to-body><el-form ref="form" :model="form" label-width="90px"><el-form-item label="处理意见"><el-input v-model="form.opinion" type="textarea" :rows="3" maxlength="1000" show-word-limit /></el-form-item><el-form-item v-if="action==='transfer'" label="新负责人" required><el-input v-model.number="form.targetOwnerId" placeholder="请输入用户ID" /></el-form-item><el-form-item v-if="action==='complete'" label="完成结果"><el-input v-model="form.contactResult" placeholder="请输入完成结果" /></el-form-item><el-form-item v-if="action==='complete'" label="完成材料"><file-upload v-model="form.fileUrl" :limit="3" /></el-form-item></el-form><div slot="footer"><el-button @click="innerVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">确认</el-button></div></el-dialog></template>
<script>export default { name:'TodoActionDialogs',props:{visible:Boolean,action:String,submitting:Boolean},data(){return{form:{opinion:'',targetOwnerId:null,contactResult:'',fileUrl:''},titles:{claim:'领取待办',start:'开始办理',submit:'提交待办',complete:'完成待办',return:'退回待办',transfer:'转派待办',cancel:'取消待办'}}},computed:{innerVisible:{get(){return this.visible},set(v){this.$emit('update:visible',v)}}},watch:{visible(v){if(v)this.form={opinion:'',targetOwnerId:null,contactResult:'',fileUrl:''}}},methods:{submit(){const payload={};if(this.form.targetOwnerId)payload.targetOwnerId=this.form.targetOwnerId;if(this.form.contactResult)payload.contactResult=this.form.contactResult;this.$emit('submit',{opinion:this.form.opinion,payload,fileUrl:this.form.fileUrl})}} }</script>
